    @Override
    protected @NotNull MTEMultiBlockBaseGui<?> getGui() {
        return new MTESpaceAssemblyLineGUI(this);
    }

    private boolean addDroneHatch(IGregTechTileEntity aBaseMetaTileEntity, int aBaseCasingIndex) {
        IMetaTileEntity aMetaTileEntity = aBaseMetaTileEntity.getMetaTileEntity();
        if (aMetaTileEntity == null) return false;
        if (aMetaTileEntity instanceof MTEHatch hatch) {
            hatch.updateTexture(aBaseCasingIndex);
            hatch.updateCraftingIcon(this.getMachineCraftingIcon());
        }
        if (aMetaTileEntity instanceof MTESpaceAssemblyLineCarrierDroneBus tDroneHatch) {
            return droneHatchs.add(tDroneHatch);
        }

        return false;
    }

    private List<SpaceCarrierDrone> getCarrierDrones() {
        return droneHatchs.stream()
            .map(MTESpaceAssemblyLineCarrierDroneBus::getDroneOrNull)
            .filter(Objects::nonNull)
            .collect(Collectors.toList());
    }

    @Override
    protected void setProcessingLogicPower(ProcessingLogic logic) {
        logic.setUnlimitedTierSkips();
        if (mExoticEnergyHatches.isEmpty() && !debugEnergyPresent) {
            logic.setAvailableVoltage(GTUtility.roundUpVoltage(this.getMaxInputVoltage()));
            logic.setAvailableAmperage(1L);
        } else super.setProcessingLogicPower(logic);
    }

    protected ProcessingLogic createProcessingLogic() {
        return new ProcessingLogic() {

            @NotNull
            @Override
            protected OverclockCalculator createOverclockCalculator(@NotNull GTRecipe recipe) {
                List<SpaceCarrierDrone> drones = getCarrierDrones();
                int efficiency = CarrierDroneLogic.evaluate(drones, recipe.mInputs.length + recipe.mFluidInputs.length);
                return OverclockCalculator.ofNoOverclock(recipe)
                    .setDuration((int) Math.ceil(recipe.mDuration * GTUtility.log2(efficiency) ));
                    // .setDurationUnderOneTickSupplier(() -> recipe.mDuration * GTUtility.powInt(0.9f, height - 4));
            }
        };
    }

