    static class CarrierDroneLogic {

        private static final int PERFECT_SYNC_BONUS = 5000; // bonus Score when all drones have perfectly equal energy
        private static final double PERFECT_MATCH_MULTIPLIER = 1.50; // bonus If exactly enough drones
        private static final double EXCESS_DRONE_PENALTY = 0.09; // > 0.05 = harsher, < 0.05 = softer
        private static final double UNDERSTAFFED_PENALTY_FACTOR = 2.0; // > 1.0 = harsher, < 1.0 = softer

        public static int evaluate(List<SpaceCarrierDrone> drones, int size) {
            if (drones == null || drones.isEmpty()) return 1;

            int n = drones.size();

            // --- Energy uniformity score ---
            double avgEnergy = drones.stream()
                .mapToInt(SpaceCarrierDrone::getEnergy)
                .average()
                .orElse(0);

            // Variance: measure how spread out the energies are
            double variance = drones.stream()
                .mapToDouble(d -> Math.pow(d.getEnergy() - avgEnergy, 2))
                .average()
                .orElse(0);

            double stdDev = Math.sqrt(variance);

            // Base score: high when uniform, decreases with spread
            // stdDev of 0 => full PERFECT_SYNC_BONUS, stdDev of 500 => ~0
            int energyScore;
            if (stdDev == 0) {
                energyScore = PERFECT_SYNC_BONUS;
            } else {
                // Penalty scaled to stdDev; cap at 0
                energyScore = (int) Math.max(0, PERFECT_SYNC_BONUS - (stdDev * 4));
            }

            // --- Outlier penalty ---
            // Having one drone far below others is worse than all drones being low.
            // We detect outliers as drones more than 1 stdDev below average.
            if (stdDev > 0) {
                long outliers = drones.stream()
                    .filter(d -> d.getEnergy() < avgEnergy - stdDev)
                    .count();
                // Each outlier costs an extra flat penalty
                energyScore -= (int) (outliers * 150);
                energyScore = Math.max(0, energyScore);
            }

            // --- Fleet size vs cargo size ---
            int score;
            if (n == size) {
                score = (int) (energyScore * PERFECT_MATCH_MULTIPLIER);
            } else if (n > size) {
                int excess = n - size;
                score = (int) (energyScore * (1.0 - (excess * EXCESS_DRONE_PENALTY)));
            } else {
                double ratio = (double) size / n;
                score = (int) (energyScore / (ratio * UNDERSTAFFED_PENALTY_FACTOR));
            }

            System.out.println("n="+n+ " size="+size+ " variance="+variance+ " stdDev="+stdDev+ " energyScore="+energyScore+ " score="+score);

            return Math.max(1, score);
        }
    }
